grid = [
[8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,8,8,5,8,8,8,8,8,5,8,8],
[8,5,5,8,8,8,8,8,5,8,8,5,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8],
[8,8,8,8,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,5,8,8,8]
]
h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
# Between consecutive 5s on each row/column, fill background cells with 3.
for r in range(h):
    marks=[c for c,v in enumerate(grid[r]) if v==5]
    for a,b in zip(marks,marks[1:]):
        for c in range(a+1,b):
            if grid[r][c] != 5: out[r][c]=3
for c in range(w):
    marks=[r for r in range(h) if grid[r][c]==5]
    for a,b in zip(marks,marks[1:]):
        for r in range(a+1,b):
            if grid[r][c] != 5: out[r][c]=3
print('shape',h,w,'row lengths',[len(r) for r in out])
print(out)
